import { useCallback, useId, useMemo, useState } from 'react';
import { Button, Input } from '@jinx-ui/react';

type StepId = 'contacts' | 'address' | 'review';

export type SignupValues = {
  fullName: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
};

type SignupWizardProps = {
  onSubmit: (values: SignupValues) => void;
  initialValues?: Partial<SignupValues>;
};

const STEPS: { id: StepId; title: string }[] = [
  { id: 'contacts', title: 'Контакты' },
  { id: 'address', title: 'Адрес' },
  { id: 'review', title: 'Проверка' },
];

const EMPTY_VALUES: SignupValues = {
  fullName: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

const REVIEW_ROWS: { key: keyof SignupValues; label: string }[] = [
  { key: 'fullName', label: 'Имя' },
  { key: 'email', label: 'E-mail' },
  { key: 'phone', label: 'Телефон' },
  { key: 'country', label: 'Страна' },
  { key: 'city', label: 'Город' },
  { key: 'street', label: 'Улица, дом' },
  { key: 'zip', label: 'Индекс' },
];

export default function SignupWizard({ onSubmit, initialValues }: SignupWizardProps) {
  const fieldId = useId();
  const [stepIndex, setStepIndex] = useState(0);
  const [values, setValues] = useState<SignupValues>({ ...EMPTY_VALUES, ...initialValues });

  const step = STEPS[stepIndex];
  const isLast = stepIndex === STEPS.length - 1;
  const isFirst = stepIndex === 0;

  const setValue = useCallback(
    (key: keyof SignupValues) => (event: { currentTarget: { value: string } }) => {
      const next = event.currentTarget.value;
      setValues((current) => ({ ...current, [key]: next }));
    },
    [],
  );

  const canAdvance = useMemo(() => {
    if (step.id === 'contacts') {
      return values.fullName.trim() !== '' && values.email.trim() !== '';
    }
    if (step.id === 'address') {
      return values.country.trim() !== '' && values.city.trim() !== '' && values.street.trim() !== '';
    }
    return true;
  }, [step.id, values]);

  const goBack = useCallback(() => {
    setStepIndex((current) => Math.max(0, current - 1));
  }, []);

  const goNext = useCallback(() => {
    setStepIndex((current) => Math.min(STEPS.length - 1, current + 1));
  }, []);

  const handleSubmit = useCallback(
    (event: React.FormEvent<HTMLFormElement>) => {
      event.preventDefault();
      if (!isLast) {
        if (canAdvance) goNext();
        return;
      }
      onSubmit(values);
    },
    [canAdvance, goNext, isLast, onSubmit, values],
  );

  const renderField = (key: keyof SignupValues, label: string, type = 'text') => (
    <div
      className="jx-field"
      style={{ display: 'grid', gap: 'var(--jx-space-1)' }}
    >
      <label className="jx-label" htmlFor={`${fieldId}-${key}`}>
        {label}
      </label>
      <Input
        id={`${fieldId}-${key}`}
        type={type}
        value={values[key]}
        onChange={setValue(key)}
        autoComplete="off"
      />
    </div>
  );

  return (
    <form className="jx-card jx-stack" onSubmit={handleSubmit} noValidate>
      <ol
        className="jx-steps"
        style={{
          display: 'flex',
          gap: 'var(--jx-space-3)',
          listStyle: 'none',
          margin: 0,
          padding: 0,
        }}
      >
        {STEPS.map((item, index) => {
          const state = index === stepIndex ? 'current' : index < stepIndex ? 'done' : 'todo';
          return (
            <li
              key={item.id}
              className={`jx-step jx-step--${state}`}
              aria-current={index === stepIndex ? 'step' : undefined}
              style={{
                display: 'flex',
                alignItems: 'center',
                gap: 'var(--jx-space-2)',
                color: index === stepIndex ? 'var(--jx-fg)' : 'var(--jx-fg-muted)',
              }}
            >
              <span
                className="jx-badge"
                style={{
                  borderRadius: 'var(--jx-radius)',
                  padding: '0 var(--jx-space-2)',
                }}
              >
                {index + 1}
              </span>
              <span className="jx-step__title">{item.title}</span>
            </li>
          );
        })}
      </ol>

      <section
        className="jx-stack"
        aria-label={step.title}
        style={{ display: 'grid', gap: 'var(--jx-space-3)', padding: 'var(--jx-space-4) 0' }}
      >
        {step.id === 'contacts' && (
          <>
            {renderField('fullName', 'Имя и фамилия')}
            {renderField('email', 'E-mail', 'email')}
            {renderField('phone', 'Телефон', 'tel')}
          </>
        )}

        {step.id === 'address' && (
          <>
            {renderField('country', 'Страна')}
            {renderField('city', 'Город')}
            {renderField('street', 'Улица, дом')}
            {renderField('zip', 'Индекс')}
          </>
        )}

        {step.id === 'review' && (
          <dl
            className="jx-list"
            style={{ display: 'grid', gap: 'var(--jx-space-2)', margin: 0 }}
          >
            {REVIEW_ROWS.map((row) => (
              <div
                key={row.key}
                style={{
                  display: 'grid',
                  gridTemplateColumns: 'minmax(0, 12rem) minmax(0, 1fr)',
                  gap: 'var(--jx-space-2)',
                }}
              >
                <dt className="jx-label" style={{ color: 'var(--jx-fg-muted)' }}>
                  {row.label}
                </dt>
                <dd style={{ margin: 0, color: 'var(--jx-fg)' }}>{values[row.key] || '—'}</dd>
              </div>
            ))}
          </dl>
        )}
      </section>

      <footer
        className="jx-cluster"
        style={{ display: 'flex', justifyContent: 'space-between', gap: 'var(--jx-space-2)' }}
      >
        <Button type="button" variant="ghost" onClick={goBack} disabled={isFirst}>
          Назад
        </Button>
        {isLast ? (
          <Button type="submit" variant="primary">
            Отправить
          </Button>
        ) : (
          <Button type="button" variant="primary" onClick={goNext} disabled={!canAdvance}>
            Дальше
          </Button>
        )}
      </footer>
    </form>
  );
}

